import java.util.*;public class Q9_Multiple_Exception_Handling{public static void main(String[]x){Scanner s=new Scanner(System.in);try{System.out.print("Enter two numbers: ");int a=s.nextInt(),b=s.nextInt();System.out.println("Result: "+(a/b));}catch(ArithmeticException e){System.out.println("Error: Cannot divide by zero.");}catch(InputMismatchException e){System.out.println("Error: Please enter numeric integers only.");}finally{System.out.println("Program Execution Completed");s.close();}}}
